{
  "title": "CSCI-140 Foundations Companion",
  "learningObjectives": [
    "Identify core data structures (lists, stacks, queues, trees, graphs) and their access patterns as defined in the course catalog.",
    "Explain the role of objects, classes, and inheritance in achieving cohesion and minimal coupling within software systems.",
    "Apply exception handling and input/output streams to manage runtime errors and user interaction in Python programs."
  ],
  "beats": [
    {
      "title": "Problem Statement and Algorithmic Foundations",
      "claim": "Programming begins with precise problem statements, input and output examples, and algorithms written independently of syntax.",
      "example": "A student defines a sorting problem by listing input arrays and expected sorted outputs before writing any code.",
      "visualDirection": "Display a split-screen: left side shows a textual problem statement with input/output examples; right side shows a flowchart of the algorithmic steps.",
      "sourceIds": ["opendsa-programming-foundations"]
    },
    {
      "title": "Data Representation: Lists, Stacks, and Queues",
      "claim": "Lists represent ordered sequences, stacks use last-in first-out access, and queues use first-in first-out access.",
      "example": "A stack of plates is added and removed only from the top, while a line of people waiting for a bus is processed from the front.",
      "visualDirection": "Animate three separate diagrams: a linear list with indices, a stack with arrows pointing only to the top element, and a queue with arrows entering at the tail and leaving at the head.",
      "sourceIds": ["opendsa-programming-foundations"]
    },
    {
      "title": "Hierarchical and Connected Structures",
      "claim": "Trees represent hierarchy and graphs represent connected entities, forming the basis for nested data structures.",
      "example": "A family tree illustrates hierarchical relationships, while a subway map illustrates a graph of connected stations.",
      "visualDirection": "Render a binary tree diagram with labeled nodes and edges, followed by a directed graph with multiple cycles and labeled vertices.",
      "sourceIds": ["opendsa-programming-foundations", "rit-csci-140"]
    },
    {
      "title": "Objects, Classes, and Inheritance",
      "claim": "Objects have identity, a type, and a value; classes define these attributes and support inheritance to create new types.",
      "example": "A 'Dog' class inherits from an 'Animal' class, gaining shared attributes like 'name' while adding specific ones like 'bark'.",
      "visualDirection": "Show a UML class diagram with an 'Animal' superclass and a 'Dog' subclass, highlighting the inheritance arrow and instance attributes.",
      "sourceIds": ["python-language-reference", "rit-csci-140"]
    },
    {
      "title": "Software Qualities: Cohesion and Coupling",
      "claim": "Cohesion measures how related the responsibilities of a module are, while minimal coupling ensures modules depend on few others.",
      "example": "A 'PaymentProcessor' class has high cohesion because it handles only payment logic, and low coupling because it does not directly access database tables.",
      "visualDirection": "Present two side-by-side code snippets: one tightly coupled with multiple imports and direct variable access, and one loosely coupled using interfaces or abstract classes.",
      "sourceIds": ["rit-csci-140"]
    },
    {
      "title": "Abstract Data Types and Collection Libraries",
      "claim": "Object-oriented collection class libraries provide ready-made implementations for stacks, queues, maps, and trees.",
      "example": "Using Python's collections module, a developer instantiates a deque as a stack or a defaultdict as a map without writing low-level logic.",
      "visualDirection": "Display a table listing Python collection classes (e.g., list, deque, dict, defaultdict) with brief descriptions of their primary operations.",
      "sourceIds": ["rit-csci-140"]
    },
    {
      "title": "Exception Handling and Control Flow",
      "claim": "Exceptions interrupt normal control flow until a matching handler processes them or they propagate, allowing robust error management.",
      "example": "A division-by-zero error is caught by a try/except block that logs the error and returns a default value instead of crashing.",
      "visualDirection": "Animate a program execution trace where a normal flow is interrupted by an exception, jumps to a handler block, and then resumes.",
      "sourceIds": ["python-language-reference", "opendsa-programming-foundations"]
    },
    {
      "title": "Input and Output Streams",
      "claim": "Input and output streams provide the mechanisms for reading data from external sources and writing results to destinations.",
      "example": "A program reads a text file using sys.stdin and writes formatted results to a log file using open('log.txt', 'w').",
      "visualDirection": "Show a diagram with arrows labeled 'read' entering a buffer and 'write' exiting to a file icon, alongside code snippets for both operations.",
      "sourceIds": ["rit-csci-140"]
    },
    {
      "title": "Graphical User Interfaces",
      "claim": "Graphical user interfaces enable interactive software by combining visual elements with event-driven input handling.",
      "example": "A simple GUI window displays a button; clicking the button triggers a function that updates a label on the screen.",
      "visualDirection": "Render a mockup of a window with a button and a label, then highlight the button press event and the subsequent label update.",
      "sourceIds": ["rit-csci-140"]
    },
    {
      "title": "Practical Analysis Checklist",
      "claim": "Correctness arguments, tests, tracing, and debugging compare intended behavior with observable results, including boundary and error cases.",
      "example": "A developer writes unit tests for a sorting function, traces its execution on an empty list and a reversed list, and fixes a bug where the loop condition fails at the boundary.",
      "visualDirection": "Present a checklist graphic with four items: 'Write Tests', 'Trace Execution', 'Identify Boundary Cases', 'Debug and Verify', each accompanied by a small icon.",
      "sourceIds": ["opendsa-programming-foundations", "python-language-reference"]
    }
  ]
}
